#include "nondecreasing.hpp"


// ---- VIT harness: generated by translation-loop harness/emit.py ----
// Replaces the LLM-written make_valid_input(). Do not hand-edit: regenerate.
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <vector>
#include <string>

namespace vitharness {

static const int32_t MARKER = 0x5649545F;

struct Reader {
    std::vector<unsigned char> buf;
    size_t at = 0;
    explicit Reader(const char* path) {
        FILE* f = fopen(path, "rb");
        if (!f) { fprintf(stderr, "cannot open case file %s\n", path); exit(2); }
        fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
        buf.resize((size_t)n);
        if (n > 0 && fread(buf.data(), 1, (size_t)n, f) != (size_t)n) {
            fprintf(stderr, "short read on %s\n", path); exit(2);
        }
        fclose(f);
    }
    bool done() const { return at >= buf.size(); }
    void take(void* dst, size_t n) {
        if (at + n > buf.size()) { fprintf(stderr, "case stream truncated\n"); exit(2); }
        memcpy(dst, buf.data() + at, n); at += n;
    }
    // A desynchronised stream would otherwise compare whatever it read next and
    // report agreement on it.
    void marker(int c) {
        int32_t m = 0; take(&m, sizeof(m));
        if (m != MARKER) { fprintf(stderr, "case %d: stream desync\n", c); exit(2); }
    }
    double d() { double v; take(&v, sizeof(v)); return v; }
    float  f() { float  v; take(&v, sizeof(v)); return v; }
    int32_t i() { int32_t v; take(&v, sizeof(v)); return v; }
    void ds(double* p, int n) { take(p, sizeof(double) * (size_t)n); }
    // A REAL(ReKi) crosses as float, and the stream carries float32 for it.
    // Reading it as double would consume twice the bytes and desync the case.
    void fs(float* p, int n) { take(p, sizeof(float) * (size_t)n); }
    void is(int32_t* p, int n) { take(p, sizeof(int32_t) * (size_t)n); }
    // A CHARACTER argument is one byte per character. NOT NUL-terminated: the
    // length crosses as its own parameter and is the only statement of extent.
    void cs(char* p, int n) { take(p, (size_t)n); }
};

struct Diff { int cse; std::string output; std::string ref; std::string got; };

static std::string hexbytes(const void* p, size_t n) {
    static const char* H = "0123456789abcdef";
    const unsigned char* b = (const unsigned char*)p;
    std::string s;
    size_t lim = n < 32 ? n : 32;
    for (size_t k = 0; k < lim; k++) { s += H[b[k] >> 4]; s += H[b[k] & 15]; }
    if (n > lim) s += "...";
    return s;
}

// memcmp, never ==: -0.0 vs +0.0 and NaN vs NaN are real discriminators, and a
// tolerance would hide the rounding differences this method exists to find.
static bool same(const void* a, const void* b, size_t n) { return memcmp(a, b, n) == 0; }

static std::string esc(const std::string& s) {
    std::string o; for (char c : s) { if (c == '"' || c == '\\') o += '\\'; o += c; } return o;
}

}  // namespace vitharness


using namespace vitharness;

extern "C" void nondecreasing_f90(double* Array, int n_Array, int32_t* vit_result);

int main(int argc, char** argv) {
    const char* path = argc > 1 ? argv[1] : "nondecreasing_cases.bin";
    Reader r(path);
    int checked = 0, failed = 0, inadmissible = 0;
    std::vector<Diff> diffs;
    for (int c = 0; c < 25; c++) {
        r.marker(c);
        std::vector<double> Array_a(n_Array_a);
        r.ds(Array_a.data(), (int)(n_Array_a));
        std::vector<double> Array_b = Array_a;
        double n_Array_a = (double)r.i();
        double n_Array_b = n_Array_a;

        int32_t ret_a = NonDecreasing(Array_a.data(), n_Array_a);
        int32_t ret_b = 0;
        nondecreasing_f90(Array_b.data(), n_Array_b, &ret_b);
        int bad = 0;
        #define VITCMP(nm, pa, pb, sz) \
            if (!same((pa), (pb), (sz))) { bad++; if (diffs.size() < 16) \
                diffs.push_back(Diff{c, nm, hexbytes((pb), (sz)), hexbytes((pa), (sz))}); }
        VITCMP("vit_result", &ret_a, &ret_b, sizeof(ret_a));
        VITCMP("Array", Array_a.data(), Array_b.data(), sizeof(double) * Array_a.size());
        #undef VITCMP
        checked++;
        if (bad) failed++;
    }

    printf("{\n");
    printf(" \"unit\": \"NonDecreasing\",\n");
    printf(" \"against\": \"translation\",\n");
    printf(" \"checked\": %d,\n", checked);
    printf(" \"failed\": %d,\n", failed);
    printf(" \"inadmissible\": %d,\n", inadmissible);
    printf(" \"rule_coverage\": [\n");
    printf("  \"%s\",\n", "  applied  R5_non_degenerate_shape    1 varied extent(s) at [3], NO index parameter identified, array elements distinct");
    printf("  \"%s\",\n", "  N/A      R2_flag_values             no enumerated-value parameter -- no branch this rule can reach");
    printf("  \"%s\",\n", "  N/A      R6_reference_literals      no real, no INTEGER and no CHARACTER parameter -- no boundary this rule can reach");
    printf("  \"%s\",\n", "  applied  R3_no_dead_signal          1 real value(s), none zero in every case");
    printf("  \"%s\",\n", "  applied  R1_direct_call             the unit is called directly; no scenario can fail to reach it");
    printf("  \"%s\"\n", "  applied  R4_compare_all_outputs     return value + 0 out-parameter(s): none");
    printf(" ],\n");
    printf(" \"mismatches\": [\n");
    for (size_t k = 0; k < diffs.size(); k++)
        printf("  {\"case\": %d, \"output\": \"%s\", \"ref\": \"%s\", \"got\": \"%s\"}%s\n",
               diffs[k].cse, esc(diffs[k].output).c_str(),
               diffs[k].ref.c_str(), diffs[k].got.c_str(),
               k + 1 < diffs.size() ? "," : "");
    printf(" ]\n}\n");
    return failed > 0 ? 1 : 0;
}
